class XDREnum(object):
    __slots__ = ['name', 'value']
    def __init__(self, name, value):
        self.name = name
        self.value = value
    def __int__(self):
        return self.value
    def __str__(self):
        return self.name
    def __repr__(self):
        return self.name
    def __cmp__(x, y):
        return cmp(int(x), int(y))
    def __hash__(self):
        return hash(int(self))
