    @DisplayName("addNeighbor() should return the edge to the new neighbor")
    void addNeighbor_newNeighbor() {
        val edge = vertex.addNeighbor(7, "seven");
        assertEquals(7, edge.getEnd());
        assertEquals("seven", edge.getLabel());
    }
